// indicators.hpp — reconstruction of the C++ library header used by
// /workspace/dataset/test2.cpp, recovered from the disassembly of
// /workspace/dataset/test2_executable.
//
//   indicators::ProgressBar::ProgressBar()  @ 0x402790
//   indicators::ProgressBar::~ProgressBar() @ 0x402880
//   indicators::ProgressBar::str() const    @ 0x402b20
//   indicators::Percentage::str()           inlined into main (0x4022b4..0x4023d3)
//
// Field layout recovered from the ctor:
//   @0x00 int         progress         = 0
//   @0x04 int         total            = 100
//   @0x08 int         width            = 50    (movl $0x32)
//   @0x0c bool        show_percentage  = true
//   @0x0d bool        show_bar         = true
//   @0x10 std::string fill             = "="
//   @0x18 std::string lead             = ">"
//   @0x20 std::string remainder        = " "
//   @0x28 std::string start            = "["
//   @0x30 std::string end              = "]"

#ifndef INDICATORS_HPP
#define INDICATORS_HPP

#include <iomanip>
#include <sstream>
#include <string>

namespace indicators {

class ProgressBar {
public:
  ProgressBar()
      : progress(0), total(100), width(50), show_percentage(true),
        show_bar(true), fill("="), lead(">"), remainder(" "), start("["),
        end("]") {}

  void set_progress(int value) { progress = value; }
  void set_total(int value) { total = value; }
  void set_width(int value) { width = value; }
  void set_show_percentage(bool value) { show_percentage = value; }
  void set_show_bar(bool value) { show_bar = value; }
  void set_fill(const std::string &value) { fill = value; }
  void set_lead(const std::string &value) { lead = value; }
  void set_remainder(const std::string &value) { remainder = value; }
  void set_start(const std::string &value) { start = value; }
  void set_end(const std::string &value) { end = value; }

  int get_progress() const { return progress; }
  int get_total() const { return total; }
  int get_width() const { return width; }

  // 0x402b20
  std::string str() const {
    std::ostringstream os;
    if (show_bar) {                                     // cmpb 0xd(%rbx)
      os << start;                                      // 0x28(%rbx)
      // cvtsi2ssl progress ; cvtsi2ssl total ; divss ;
      // cvtsi2ss width ; mulss ; cvttss2si
      int completed = static_cast<int>(
          static_cast<float>(progress) / static_cast<float>(total) *
          static_cast<float>(width));
      for (int i = 0; i < width; ++i) {                 // skipped when width<=0
        if (completed > i)
          os << fill;                                   // 0x10(%rbx)
        else if (completed == i)
          os << lead;                                   // 0x18(%rbx)
        else
          os << remainder;                              // 0x20(%rbx)
      }
      os << end;                                        // 0x30(%rbx)
    }
    if (show_percentage) {                              // cmpb 0xc(%rbx)
      if (show_bar)
        os << " ";
      // divss -> cvtss2sd -> mulsd 100.0 -> _M_insert<double>
      os << std::fixed << std::setprecision(1)
         << (static_cast<double>(static_cast<float>(progress) /
                                 static_cast<float>(total)) *
             100.0)
         << "%";
    }
    return os.str();
  }

private:
  int progress;
  int total;
  int width;
  bool show_percentage;
  bool show_bar;
  std::string fill;
  std::string lead;
  std::string remainder;
  std::string start;
  std::string end;
};

class Percentage {
public:
  explicit Percentage(float value_) : value(value_) {}

  void set_value(float value_) { value = value_; }
  float get_value() const { return value; }

  std::string str() const {
    std::ostringstream os;
    os << std::fixed << std::setprecision(1)
       << (static_cast<double>(value) * 100.0) << "%";
    return os.str();
  }

private:
  float value;
};

} // namespace indicators

#endif // INDICATORS_HPP

// Behavioural clone of /workspace/dataset/test2.cpp (same calls, same output).
#include <iostream>
#include <string>
#include "indicators.hpp"

int main(int argc, char* argv[]) {
    indicators::ProgressBar bar;
    bar.set_progress(75);
    bar.set_total(100);
    bar.set_width(30);
    std::cout << bar.str() << std::endl;

    indicators::Percentage pct(0.75f);
    std::cout << pct.str() << std::endl;
    return 0;
}

// probe.cpp — parameterised oracle over the reconstructed indicators.hpp.
//
// Usage:
//   probe bar <progress> <total> <width>   -> ProgressBar::str() + '\n'
//   probe pct <float>                      -> Percentage::str() + '\n'
//   probe fixed1 <double>                  -> std::fixed/setprecision(1) of double + '\n'
//
// Numbers are parsed with strtol/strtod, so "inf", "-inf", "nan", "0x1p-3",
// "1e-40", "-0" etc. all work. Ints accept INT_MIN..INT_MAX (decimal, hex
// "0x..", octal "0.." via strtol base 0).

#include <cerrno>
#include <climits>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>

#include "indicators.hpp"

static void usage() {
  std::fputs("usage: probe bar <progress> <total> <width>\n"
             "       probe pct <float>\n"
             "       probe fixed1 <double>\n",
             stderr);
}

static int parse_int(const char *s, const char *what) {
  errno = 0;
  char *end = nullptr;
  long v = std::strtol(s, &end, 0);
  if (end == s) {
    std::fprintf(stderr, "probe: %s: not a number: '%s'\n", what, s);
    std::exit(2);
  }
  while (*end == ' ' || *end == '\t' || *end == '\n' || *end == '\r')
    ++end;
  if (*end != '\0') {
    std::fprintf(stderr, "probe: %s: trailing garbage: '%s'\n", what, s);
    std::exit(2);
  }
  if (errno == ERANGE || v < INT_MIN || v > INT_MAX) {
    std::fprintf(stderr, "probe: %s: out of int range: '%s'\n", what, s);
    std::exit(2);
  }
  return static_cast<int>(v);
}

static double parse_double(const char *s, const char *what) {
  errno = 0;
  char *end = nullptr;
  double v = std::strtod(s, &end);
  if (end == s) {
    std::fprintf(stderr, "probe: %s: not a number: '%s'\n", what, s);
    std::exit(2);
  }
  while (*end == ' ' || *end == '\t' || *end == '\n' || *end == '\r')
    ++end;
  if (*end != '\0') {
    std::fprintf(stderr, "probe: %s: trailing garbage: '%s'\n", what, s);
    std::exit(2);
  }
  // ERANGE (underflow/overflow) is deliberately tolerated: strtod still yields
  // the correctly-rounded 0 / +-HUGE_VAL, which is what the library would see.
  return v;
}

int main(int argc, char *argv[]) {
  if (argc < 2) {
    usage();
    return 2;
  }
  const char *cmd = argv[1];

  if (std::strcmp(cmd, "bar") == 0) {
    if (argc != 5) {
      usage();
      return 2;
    }
    indicators::ProgressBar bar;
    bar.set_progress(parse_int(argv[2], "progress"));
    bar.set_total(parse_int(argv[3], "total"));
    bar.set_width(parse_int(argv[4], "width"));
    std::cout << bar.str() << "\n";
    return 0;
  }

  if (std::strcmp(cmd, "pct") == 0) {
    if (argc != 3) {
      usage();
      return 2;
    }
    float v = static_cast<float>(parse_double(argv[2], "value"));
    indicators::Percentage pct(v);
    std::cout << pct.str() << "\n";
    return 0;
  }

  if (std::strcmp(cmd, "fixed1") == 0) {
    if (argc != 3) {
      usage();
      return 2;
    }
    double d = parse_double(argv[2], "value");
    std::ostringstream os;
    os << std::fixed << std::setprecision(1) << d;
    std::cout << os.str() << "\n";
    return 0;
  }

  std::fprintf(stderr, "probe: unknown command '%s'\n", cmd);
  usage();
  return 2;
}

// patchbin.c — clone /workspace/dataset/test2_executable with its baked-in
// constants replaced, so the GENUINE library code (ProgressBar::str() at
// 0x402b20 and the inlined Percentage/fixed1 formatting in main) can be driven
// with arbitrary inputs for differential testing against probe.
//
// File offsets (vaddr - 0x400000; .text and .rodata are both identity-mapped):
//   0x226c : movl $imm,0x28(%rsp)  -> width      (was 0x1e = 30)
//   0x3068 : int32                 -> progress   (was 0x4b = 75)
//   0x306c : int32                 -> total      (was 0x64 = 100)
//   0x3070 : double                -> the constant-folded Percentage payload
//                                     (was 75.0), printed by fixed/precision(1)
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define OFF_WIDTH 0x226c
#define OFF_PROGRESS 0x3068
#define OFF_TOTAL 0x306c
#define OFF_DOUBLE 0x3070

int main(int argc, char **argv) {
  if (argc != 7) {
    fprintf(stderr,
            "usage: patchbin <in> <out> <progress> <total> <width> <double>\n");
    return 2;
  }
  FILE *fi = fopen(argv[1], "rb");
  if (!fi) { perror("open in"); return 1; }
  static unsigned char buf[1 << 20];
  size_t n = fread(buf, 1, sizeof buf, fi);
  fclose(fi);
  if (n < OFF_DOUBLE + 8) { fprintf(stderr, "too small\n"); return 1; }

  /* sanity: refuse to patch if the expected original constants aren't there */
  int w0; memcpy(&w0, buf + OFF_WIDTH, 4);
  int p0; memcpy(&p0, buf + OFF_PROGRESS, 4);
  int t0; memcpy(&t0, buf + OFF_TOTAL, 4);
  double d0; memcpy(&d0, buf + OFF_DOUBLE, 8);
  if (w0 != 30 || p0 != 75 || t0 != 100 || d0 != 75.0) {
    fprintf(stderr, "unexpected originals: w=%d p=%d t=%d d=%f\n", w0, p0, t0, d0);
    return 1;
  }

  int progress = (int)strtol(argv[3], NULL, 0);
  int total = (int)strtol(argv[4], NULL, 0);
  int width = (int)strtol(argv[5], NULL, 0);
  double dv = strtod(argv[6], NULL);
  memcpy(buf + OFF_PROGRESS, &progress, 4);
  memcpy(buf + OFF_TOTAL, &total, 4);
  memcpy(buf + OFF_WIDTH, &width, 4);
  memcpy(buf + OFF_DOUBLE, &dv, 8);

  FILE *fo = fopen(argv[2], "wb");
  if (!fo) { perror("open out"); return 1; }
  fwrite(buf, 1, n, fo);
  fclose(fo);
  return 0;
}
